<?php
/**
 * XML sitemap generator.
 *
 * Only public URLs are listed: published pages and posts (plus anything whose
 * scheduled time has already passed), published services and blog categories.
 * Drafts, scheduled-but-not-yet-due posts and noindex rows are never included.
 *
 * The file is regenerated by api/cron/build-sitemap.php (hourly) and
 * immediately after the scheduler publishes something.
 */

declare(strict_types=1);

namespace Shn\Services;

use Shn\Helpers\Config;
use Shn\Models\BlogModel;
use Shn\Models\PageModel;
use Shn\Models\ServiceModel;
use Throwable;

final class SitemapBuilder
{
    public function __construct(
        private readonly PageModel $pages = new PageModel(),
        private readonly BlogModel $blog = new BlogModel(),
        private readonly ServiceModel $services = new ServiceModel(),
    ) {
    }

    /** @return array<int,array{loc:string,lastmod:?string,changefreq:string,priority:float}> */
    public function entries(): array
    {
        $base = $this->baseUrl();
        $today = gmdate('Y-m-d');

        $entries = [];
        $seen = [];

        $add = static function (string $loc, ?string $lastmod, string $changefreq, float $priority) use (&$entries, &$seen): void {
            if (isset($seen[$loc])) {
                return;
            }
            $seen[$loc] = true;
            $entries[] = [
                'loc' => $loc,
                'lastmod' => $lastmod,
                'changefreq' => $changefreq,
                'priority' => $priority,
            ];
        };

        // Fixed marketing routes that always exist in the SPA.
        $add($base . '/', $today, 'weekly', 1.0);
        $add($base . '/services', $today, 'weekly', 0.9);
        $add($base . '/how-it-works', $today, 'monthly', 0.8);
        $add($base . '/service-area', $today, 'monthly', 0.7);
        $add($base . '/about', $today, 'monthly', 0.7);
        $add($base . '/contact', $today, 'monthly', 0.8);
        $add($base . '/blog', $today, 'daily', 0.9);

        foreach ($this->services->publishedList() as $service) {
            $add($base . '/services/' . $service['slug'], null, 'monthly', 0.8);
        }

        foreach ($this->pages->publicIndex() as $page) {
            $slug = (string) ($page['slug'] ?? '');
            if ($slug === '' || $slug === '/' || (int) ($page['noindex'] ?? 0) === 1) {
                continue;
            }
            $lastmod = $this->isoDate((string) ($page['updated_at'] ?? ''));
            $add($base . rtrim($slug, '/'), $lastmod, 'monthly', $slug === '/privacy-policy' ? 0.3 : 0.6);
        }

        foreach ($this->blog->publicCategories() as $category) {
            if ((int) ($category['noindex'] ?? 0) === 1) {
                continue;
            }
            $add($base . '/blog/category/' . $category['slug'], null, 'weekly', 0.6);
        }

        // Paginate through the public blog so 30+ posts are all included.
        $page = 1;
        do {
            $result = $this->blog->publicIndex([], $page, 100);
            foreach ($result['items'] as $post) {
                $add(
                    $base . '/blog/' . $post['slug'],
                    $this->isoDate((string) ($post['published_at'] ?? '')),
                    'monthly',
                    0.7,
                );
            }
            $lastPage = (int) ceil(((int) ($result['meta']['total'] ?? 0)) / 100);
            $page++;
        } while ($page <= $lastPage && $page <= 20);

        return $entries;
    }

    public function xml(): string
    {
        $lines = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<!-- Generated from the database by api/cron/build-sitemap.php — do not edit by hand. -->',
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
        ];

        foreach ($this->entries() as $entry) {
            $lines[] = '  <url>';
            $lines[] = '    <loc>' . $this->escape($entry['loc']) . '</loc>';
            if (!empty($entry['lastmod'])) {
                $lines[] = '    <lastmod>' . $entry['lastmod'] . '</lastmod>';
            }
            $lines[] = '    <changefreq>' . $entry['changefreq'] . '</changefreq>';
            $lines[] = '    <priority>' . number_format($entry['priority'], 1) . '</priority>';
            $lines[] = '  </url>';
        }

        $lines[] = '</urlset>';

        return implode("\n", $lines) . "\n";
    }

    /** Writes the sitemap and returns the byte count (0 when it cannot write). */
    public function write(?string $path = null): int
    {
        $path ??= $this->path();
        $xml = $this->xml();

        $dir = dirname($path);
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }

        $written = @file_put_contents($path, $xml, LOCK_EX);
        if ($written === false) {
            throw new \RuntimeException('Cannot write the sitemap to ' . $path . ' — check the folder permissions or set SITEMAP_PATH.');
        }

        return (int) $written;
    }

    public function path(): string
    {
        $path = (string) Config::string('sitemap.path', '');
        if ($path !== '') {
            return $path;
        }
        return dirname(__DIR__, 2) . '/public/sitemap.xml';
    }

    public function baseUrl(): string
    {
        return rtrim((string) Config::string('site.url', 'https://safehomenetwork.com'), '/');
    }

    /** Last successful write, used by the admin panel. */
    public function lastUpdated(): ?string
    {
        $path = $this->path();
        if (!is_file($path)) {
            return null;
        }
        $time = @filemtime($path);
        return $time === false ? null : gmdate('c', $time);
    }

    private function isoDate(string $value): ?string
    {
        if (trim($value) === '') {
            return null;
        }
        $timestamp = strtotime($value);
        return $timestamp === false ? null : gmdate('Y-m-d', $timestamp);
    }

    private function escape(string $value): string
    {
        return htmlspecialchars($value, ENT_XML1 | ENT_QUOTES, 'UTF-8');
    }
}
